css:
.wrap{ width: 100%; max-width: 1484px; margin-left: auto; margin-right: auto; padding-left: 40px; padding-right: 40px; box-sizing: border-box; }
.sr-only{ position: absolute; width: 1px; height: 1px; padding: 0; margin: -1px; overflow: hidden; clip: rect(0 0 0 0); white-space: nowrap; border: 0; }
@media screen and (max-width: 767px){.wrap{ padding-left: 20px; padding-right: 20px; }}
.hero-section { padding-top: 150px; padding-bottom: 150px; background-color: #13181d; color: #ffffff; font-family: Switzer, Arial, sans-serif; scroll-margin-top: 120px; }
.hero-statement { max-width: 1240px; margin: 0 0 36px 0; font-size: 80px; line-height: 1.06; font-weight: 400; letter-spacing: -0.03em; }
.hero-statement-accent { max-width: 1240px; margin: 0; font-size: 80px; line-height: 1.06; font-weight: 400; letter-spacing: -0.03em; color: #f7ff88; }
.hero-panel { max-width: 920px; margin: 140px 0 0 auto; }
.hero-panel-text { margin: 0; font-size: 30px; line-height: 1.32; font-weight: 400; letter-spacing: -0.01em; }
.hero-bridge { margin: 32px 0 0 0; padding-top: 24px; border-top: 1px solid rgba(255, 255, 255, 0.2); font-size: 20px; line-height: 1.5; color: rgba(255, 255, 255, 0.72); }

@media screen and (max-width: 991px) {
  .hero-section { padding-top: 112px; padding-bottom: 120px; }
  .hero-statement { font-size: 60px; }
  .hero-statement-accent { font-size: 60px; }
  .hero-panel { margin-top: 96px; }
  .hero-panel-text { font-size: 26px; }
}
@media screen and (max-width: 767px) {
  .hero-section { padding-top: 80px; padding-bottom: 96px; }
  .hero-statement { font-size: 44px; margin-bottom: 28px; }
  .hero-statement-accent { font-size: 44px; }
  .hero-panel { margin-top: 72px; }
  .hero-panel-text { font-size: 22px; }
  .hero-bridge { font-size: 18px; }
}
@media screen and (max-width: 479px) {
  .hero-statement { font-size: 36px; }
  .hero-statement-accent { font-size: 36px; }
  .hero-panel-text { font-size: 20px; }
}
